from pathlib import Path
p=Path('work/pocket-research/compile.cjs');s=p.read_text(encoding='utf-8');a=s.index('function ability(');i=s.index(' return null;',a)
s=s[:i]+r'''
 if((m=text.match(/^Once during your turn, you may take a \[([A-Z])\] Energy from your Energy Zone and attach it to your Active \[([A-Z])\] Pokémon\.$/)))return{activeType:m[2],program:[{kind:'zoneEnergy',active:true,amount:1,type:m[1]}]};
 if(text==='Each of your evolved Pokémon can use any attack from its previous Evolutions. (You still need the necessary Energy to use each attack.)')return{passive:{teamPreviousAttacks:true}};
 if(text==='If you have Arceus or Arceus ex in play, this Pokémon has no Retreat Cost.')return{passive:{requiresNamesAny:['Arceus','Arceus ex'],freeRetreat:true}};
 if(text==='If you have Latias in play, this Pokémon has no Retreat Cost.')return{passive:{requiresNamesAny:['Latias'],freeRetreat:true}};
 if(text==="If you have Arceus or Arceus ex in play, this Pokémon takes -30 damage from attacks.")return{passive:{requiresNamesAny:['Arceus','Arceus ex'],reduce:30}};
 if(text==="If you have Arceus or Arceus ex in play, attacks used by this Pokémon do +30 damage to your opponent's Active Pokémon.")return{passive:{requiresNamesAny:['Arceus','Arceus ex'],selfAttack:30}};
 if(text==="If you have Arceus or Arceus ex in play, attacks used by this Pokémon cost 1 less [C] Energy.")return{passive:{requiresNamesAny:['Arceus','Arceus ex'],selfCostReduction:{amount:1,type:'C'}}};
 if(text==="If you have another Falinks in play, this Pokémon's attacks do +20 damage to your opponent's Active Pokémon, and this Pokémon takes -20 damage from attacks from your opponent's Pokémon.")return{passive:{anotherName:'Falinks',selfAttack:20,reduce:20}};
 if(text==="If you have another Beldum in play, this Pokémon's Retreat Cost is 2 less.")return{passive:{anotherName:'Beldum',retreatReduction:2}};
 if(text==='Once during your turn, if you have Arceus or Arceus ex in play, you may do 30 damage to your opponent\'s Active Pokémon.')return{requiresNamesAny:['Arceus','Arceus ex'],program:[{kind:'abilityDamage',active:true,amount:30}]};
 if(text==='Once during your turn, you may switch your Active Ultra Beast with 1 of your Benched Ultra Beasts.')return{activeTag:'ultra_beasts',program:[{kind:'choosePokemon',bench:true,tag:'ultra_beasts',next:[{kind:'switch'}]}]};
 if(text==="If this Pokémon has a Pokémon Tool attached, attacks used by this Pokémon cost 1 less [G] Energy.")return{passive:{needsTool:true,selfCostReduction:{amount:1,type:'G'}}};
 if(text==="If this Pokémon's remaining HP is 50 or less, attacks used by this Pokémon do +60 damage to your opponent's Active Pokémon.")return{passive:{selfAttack:60,hpAtMost:50}};
 if(text==='As long as this Pokémon is in play, it is [W] and [F] type.')return{passive:{dualTypes:['W','F']}};
 if(text==='As long as this Pokémon is in play, it is [F] and [D] type.')return{passive:{dualTypes:['F','D']}};
 if(text==="If you don't have Regirock, Regice, and Registeel on your Bench, this Pokémon can't attack.")return{passive:{attackNeedsBench:['Regirock','Regice','Registeel']}};
 if((m=text.match(/^If this Pokémon is in the Active Spot and is Knocked Out by damage from an attack from your opponent's Pokémon, do (\d+) damage to the Attacking Pokémon\.$/)))return{passive:{koReflect:+m[1]}};
 if(text==="If this Pokémon is in the Active Spot and is Knocked Out by damage from an attack from your opponent's Pokémon, do 10 damage to each of your opponent's Pokémon.")return{passive:{koAllDamage:10}};
 if(text==="If this Pokémon is in the Active Spot and is Knocked Out by damage from an attack from your opponent's Pokémon, flip a coin. If heads, the Attacking Pokémon is Knocked Out.")return{passive:{koCoinAttacker:true}};
 if(text==="If this Pokémon would be Knocked Out by damage from an attack, flip a coin. If heads, this Pokémon is not Knocked Out, and its remaining HP becomes 10.")return{passive:{surviveAttack:true}};
 if(text==="When this Pokémon is Knocked Out, flip a coin. If heads, your opponent can't get any points for it.")return{passive:{koCoinNoPoints:true}};
 if(text==="If your opponent's Pokémon is Knocked Out by damage from this Pokémon's attacks, during your opponent's next turn, prevent all damage from—and effects of—attacks done to this Pokémon.")return{passive:{koShield:true}};
 if(text==="As long as this Pokémon is on your Bench, attacks used by your Pokémon that evolve from Poliwhirl do +40 damage to your opponent's Active Pokémon.")return{passive:{teamAttack:40,bench:true,evolvesFrom:'Poliwhirl'}};
 if(text==="This Ability works if you have any Unown in play with an Ability other than GUARD. All of your Pokémon take -10 damage from attacks from your opponent's Pokémon.")return{passive:{otherAbility:{name:'Unown',except:'GUARD'},teamReduction:10}};
 if(text==="This Ability works if you have any Unown in play with an Ability other than POWER. Attacks used by your Pokémon do +10 damage to your opponent's Active Pokémon.")return{passive:{otherAbility:{name:'Unown',except:'POWER'},teamAttack:10}};
 if(text==='Once during your turn, if this Pokémon is on your Bench, you may discard all Pokémon Tools from your opponent\'s Active Pokémon. If you do, discard this Pokémon.')return{onlyBench:true,requiresOpponentTool:true,program:[{kind:'discardTool',opponent:true},{kind:'removeSelf',destination:'discard'}]};
 if(text==='Once during your turn, you may heal 60 damage from 1 of your Pokémon ex that has any Energy attached. If you do, discard a random Energy from that Pokémon.')return{program:[{kind:'choosePokemon',ex:true,hasEnergy:true,wounded:true,next:[{kind:'heal',amount:60},{kind:'randomEnergyDiscard',chosen:true,amount:1}]}]};
 if(text==='Once during your turn, if this Pokémon is on your Bench, you may move 30 damage that your Active Pokémon has on it to this Pokémon.')return{onlyBench:true,needsHealing:'active',program:[{kind:'moveActiveDamage',amount:30}]};
 if(text==='As often as you like during your turn, you may choose 1 of your Pokémon that has damage on it, and move all of its damage to this Pokémon.')return{repeatable:true,program:[{kind:'choosePokemon',wounded:true,notSelf:true,next:[{kind:'moveDamage',all:true}]}]};
 if(text==='Once during your turn, you may discard 1 [R] Energy from this Pokémon in order to use this Ability. During this turn, attacks used by your [R] Pokémon do +50 damage to your opponent\'s Active Pokémon.')return{requiredEnergy:'R',program:[{kind:'discardEnergy',type:'R',amount:1},{kind:'attackBonus',type:'R',amount:50}]};
 if(text==='Once during your turn, you may remove a random Special Condition from your Active Pokémon.')return{program:[{kind:'cureRandom',active:true}]};
 if(text==='Once during your turn, you may flip a coin. If heads, switch in 1 of your opponent\'s Benched Pokémon to the Active Spot.')return{program:[{kind:'condition',then:[{kind:'choosePokemon',side:'opponent',bench:true,optional:true,next:[{kind:'switch'}]}]}]};
 if(text==='Once during your turn, you may use this Ability. 1 Special Condition from among Burned, Confused, and Poisoned is chosen at random, and your opponent\'s Active Pokémon is now affected by that Special Condition. Any Special Conditions already affecting that Pokémon will not be chosen.')return{program:[{kind:'randomStatus',statuses:['Burned','Confused','Poisoned']}]};
''' +s[i:];p.write_text(s,encoding='utf-8')
